if (_totalSupply != 0) {
uint256 remaining = t.periodFinish - block.timestamp;
timeData.rewardsDuration = uint32(t.rewardsDuration - remaining);
}

timeData.periodFinish = uint32(block.timestamp);

emit FarmingFinished();
